for i,item in enumerate(items):
 n=name_for(item,i);paths.append(n);related=[name_for(x,j) for j,x in enumerate(items) if x.get('storyId')==item.get('storyId') and x.get('link')!=item.get('link')][:6];url=f'https://apps.laxmannepal.com.np/Nepal-News-Hub-Pro/news-pages/{n}.html';(OUT/f'{n}.html').write_text(page(item,url,related),encoding='utf-8')
urls=['https://apps.laxmannepal.com.np/Nepal-News-Hub-Pro/']+[f'https://apps.laxmannepal.com.np/Nepal-News-Hub-Pro/news-pages/{n}.html' for n in paths];xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{escape(u)}</loc></url>' for u in dict.fromkeys(urls))+'</urlset>'; (ROOT/'sitemap.xml').write_text(xml,encoding='utf-8')
